{
    private const string PreguntaQ10 = "¿Cuántas faltas tengo en Bases de Datos?";
    private const string PreguntaSinDesglose = "¿Cómo voy en Bases de Datos?";
    private const string RestoSuelto = "máximo sin perder: 7).";
