        var resultado = await escenario.PreguntarAsync(Est001, PreguntaSinDesglose);

        Assert.Equal(ResultadoAuditoria.Respondida, resultado.Auditoria);
        Assert.Contains("Llevas 2 inasistencias", resultado.Respuesta!.Respuesta, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("CA", "CA-26")]
